function SendMailToAdmin(OperationId, DocumentTypeId, UserId) { //MAN Company To Send Report Request Local Mail
    var whereClause = "where Roleid = 1";
    CallGETFunctionWithParameters("/api/Users/LoadAllIDs", { pWhereClause: whereClause }, function (ids) {
        var pParametersWithValues = {
            pUserIDs: ids,
            pSubject: 'Report Request',
            pBody: "Request To print BL operation " + $("#lblOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" class="btn btn-success btn-sm" onclick="callprintmail();"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnReplyLocalEmail" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ',
            pQuotationRouteID: 0,
            pPricingID: 0,
            pRequestOrReply: 1,
            pOperationID: OperationId,
            pIsAlarm: true,
            pParentID: null, // Ensure this is assigned correctly
            pEmailSource: 801,
            pIsSendNormalEmail: false,
            // LoadWithPaging parameters
            pWhereClauseForLoadWithPaging: LocalEmails_GetWhereClause(),
            pPageSize: $("#select-page-size").val(),
            // pPageNumber is 1 because it's an insert so it will be on the top
            pPageNumber: 1,
            pOrderBy: "ID DESC",
            pSenderUserID: UserId
        }; 

        if (DocumentTypeId === 220) //bl
        {
            pParametersWithValues.pEmailSource = 801;
            pParametersWithValues.pBody = "Request To print BL : " + $("#hOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" onclick="callprintmail();" class="btn btn-success btn-sm"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnrefuse" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ';

        }
        if (DocumentTypeId === 125) // delivery order
        {
            pParametersWithValues.pEmailSource = 601;
            pParametersWithValues.pBody = "Request To print delivery order : " + $("#hOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" onclick="callprintmail();" class="btn btn-success btn-sm"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnReplyLocalEmail" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ';

        }
        if (DocumentTypeId === 130) // release letter
        {
            pParametersWithValues.pEmailSource = 701;
            pParametersWithValues.pBody = "Request To print release letter : " + $("#hOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" onclick="callprintmail();" class="btn btn-success btn-sm"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnReplyLocalEmail" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ';

        }
        if (DocumentTypeId === 135) // release letter
        {
            pParametersWithValues.pEmailSource = 702;
            pParametersWithValues.pBody = "Request To print release letter : " + $("#hOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" onclick="callprintmail();" class="btn btn-success btn-sm"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnReplyLocalEmail" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ';

        } if (DocumentTypeId === 222) // release letter
        {
            pParametersWithValues.pEmailSource = 802;
            pParametersWithValues.pBody = "Request To print AIRHBL : " + $("#hOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" onclick="callprintmail();" class="btn btn-success btn-sm"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnReplyLocalEmail" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ';

        }
        if (DocumentTypeId === 333) // release letter
        {
            pParametersWithValues.pEmailSource = 802;
            pParametersWithValues.pBody = "Request To print AIRBL  " + $("#hOperationCode").val() + '<div style=" width: 100 %; display: flex; justify- content: flex-start; align - items: center;"><button type="button" id="btnaccept" onclick="callprintmail();" class="btn btn-success btn-sm"  style=" margin-right: 40px;"  "> Click To Agree </button ><button type="button" id="btnReplyLocalEmail" class="btn btn-danger btn-sm "  style=" margin-right: 40px;"  "> Click To refuse  </button ></div> ';

        }





        CallGETFunctionWithParameters("/api/LocalEmails/SendEmail", pParametersWithValues, function (pData) {
            if (pData[0]) {
                swal("Success", "Report has been requested");
            } else {
                swal("Sorry", "Connection failed, please try again.");
            }
            FadePageCover(false);
        }, null);
    }, null);
}


function DocsOut_SubmenuTabClicked(pFadePageCover) {
    debugger;
    pFadePageCover = (pFadePageCover != undefined && pFadePageCover != null ? pFadePageCover : true);
    if ($("#tblDocsOut tbody tr").length == 0) {
        DocsOut_LoadAll($("#hOperationID").val(), null, pFadePageCover);
        //var pWhereClause = " WHERE ID = " + $("#hOperationID").val() + " OR MasterOperationID = " + $("#hOperationID").val();
        //GetListWithOpCodeAndHouseNoAndClientEmailAttr($("#hOperationID").val(), "/api/Operations/LoadWithParameters", null, "slDocsOutOperations", { pPageNumber: 1, pPageSize: 99999, pWhereClause: pWhereClause, pOrderBy: "HouseNumber" }
        //    , null);
        if ($("#tblPayables tbody tr").length == 0 && $("#tblReceivables tbody tr").length == 0) {
            Payables_LoadWithPagingWithWhereClause($("#hOperationID").val(), null, pFadePageCover);
            Receivables_LoadWithPagingWithWhereClause($("#hOperationID").val(), null, false);
        }
    }
}
