function DocsOut_Print_CargoManifest(ID) {
    debugger;
    var arr_Keys = new Array();
    var arr_Values = new Array();
    arr_Keys.push("OperationID");
    arr_Values.push(ID);

    var query = `SELECT O.ID,O.VesselName,(SELECT Notes FROM Vessels WHERE ID=O.VesselID) VesselFlag,ISNULL(CONVERT(VARCHAR(10), O.BLDate, 103), '') AS BLDate,O.POLCountryName,O.POLName,O.PODCountryName,O.PODName,O.ShipperName,O.ShipperAddress,O.ConsigneeName,O.ConsigneeAddress,O.Notify1Name,O.Notify1Address,O.MasterBL,O.DescriptionOfGoods,O.GrossWeight,O.NumberOfPackages,O.PackageTypeName, O.ACIDNumber FROM vwOperations O WHERE O.ID=${ID}`;
    let reportName = "CargoManifest";
    if (pDefaults.UnEditableCompanyName == "ATC") {
        reportName = "CargoManifest_ATC";
    }
    if (pDefaults.UnEditableCompanyName == "MAR") {
        query = `SELECT O.ID,O.VesselName,(SELECT Notes FROM Vessels WHERE ID=O.VesselID) VesselFlag,ISNULL(CONVERT(VARCHAR(10), O.BLDate, 103), '') AS BLDate,O.POLCountryName,O.POLName,O.PODCountryName,O.PODName,O.ShipperName,O.ShipperAddress,O.ConsigneeName,O.ConsigneeAddress,O.Notify1Name,O.Notify1Address,O.MasterBL,O.DescriptionOfGoods,O.MarksAndNumbers,O.GrossWeight,O.PackageTypes, O.ACIDNumber FROM vwOperations O WHERE O.ID=${ID}`;
    }
    if (pDefaults.UnEditableCompanyName == "UNF" && $("#cbHideConsignee").prop("checked") == true) {
        query = `SELECT O.ID,O.VesselName,(SELECT Notes FROM Vessels WHERE ID=O.VesselID) VesselFlag,ISNULL(CONVERT(VARCHAR(10), O.BLDate, 103), '') AS BLDate,O.POLCountryName,O.POLName,O.PODCountryName,O.PODName,O.ShipperName,O.ShipperAddress,'${getFakeConsignee()}' as ConsigneeName,'' as ConsigneeAddress,O.Notify1Name,O.Notify1Address,O.MasterBL,O.DescriptionOfGoods,O.GrossWeight,O.NumberOfPackages,O.PackageTypeName, O.ACIDNumber FROM vwOperations O WHERE O.ID=${ID}`;
    }
    if (pDefaults.UnEditableCompanyName == "TRI") {
        reportName = "CargoManifest_TRI";
        query = `SELECT O.ID,O.VesselName,(SELECT Notes FROM Vessels WHERE ID=O.VesselID) VesselFlag,ISNULL(CONVERT(VARCHAR(10), O.BLDate, 103), '') AS BLDate,O.POLCountryName,O.POLName,O.PODCountryName,O.PODName,O.ShipperName,O.ShipperAddress,O.ConsigneeName,O.ConsigneeAddress,O.Notify1Name,O.Notify1Address,O.MasterBL,O.DescriptionOfGoods,O.MarksAndNumbers,O.GrossWeight,O.NumberOfPackages,O.PackageTypeName, O.ACIDNumber FROM vwOperations O WHERE O.ID=${ID}`;
    }
    if (pDefaults.UnEditableCompanyName == "UNF" && $("#cbHideACID").prop("checked") != true && $("#cbHideConsignee").prop("checked") != true) {
        arr_Keys.push("ACID");
        arr_Values.push(1);
    } else {
        arr_Keys.push("ACID");
        arr_Values.push(0);
    }

    var pParametersWithValues =
    {
        query: query
        , arr_Keys: arr_Keys
        , arr_Values: arr_Values
        , pTitle: "Cargo Manifest"
        , pReportName: reportName
        , pReportType: "Print"
    };

    var win = window.open("", "_blank");

    url = '/ReportMainClass/PrintReportQueryAndParams?pTitle="' + pParametersWithValues.pTitle + '"'
        + '&query=' + pParametersWithValues.query + ''
        + '&arr_Keys=' + pParametersWithValues.arr_Keys + ''
        + '&arr_Values=' + pParametersWithValues.arr_Values + ''
        + '&pReportName=' + pParametersWithValues.pReportName + ''
        + '&pReportType=' + pParametersWithValues.pReportType + '';

    win.location = url;

}
