var ReportHTML = '';
function getRELDeliveryOrder(data) {
    debugger;
    let pOperationHeader = JSON.parse(data[51]);
    let pMasterBL = data[6];
    let pHouseNumber = data[7];
    let pPOLCodeAndName = data[8];
    let pPODCodeAndName = data[9];
    let pٌRoadNumber = data[52];
    return `
    <!DOCTYPE html>
        <html lang="en">
        <head>
            <meta charset="UTF-8">
            <meta name="viewport" content="width=device-width, initial-scale=1.0">
            <title>Delivery Order Flight Report</title>
            <style>
                .DOR-body p{
                    margin: 5px;
                }
                .DOR-header-code{
                    border: 2px solid;
                    width: 200px;
                    height: 80px;
                    margin-top: 100px;
                    margin-left: 40px;
                    visibility:hidden;
                }
                .DOR-header{
                    position: relative;
                    display: inline-block;
                    margin: 0;
                    font-size: 25px;
                    font-weight: 500;
                    margin-bottom: 15px;
                }
                .DOR-header::after {
                    width: 100%;
                    content: '';
                    display: block;
                    height: 1.5px;
                    background-color: black;
                    margin-top: 0px;
                }
                .DOR-header-container{
                    width: 50%;
                    margin: auto;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    justify-content: center;
                }
                .DOR-code{
                   text-align: center;
                   font-size: 24px;
                }
                .DOR-report-head{
                    display: flex;
                    width: 90%;
                    margin: auto;
                    margin-bottom: 25px;
                }
                .DOR-report-head-side{
                    width: 50%;
                    display: flex;
                    flex-direction: column;
                    justify-content: space-around;
                    align-items: start;
                }
                .underline-p{
                    text-decoration: underline;
                    display: inline-block;
                }
                .underline-p span{
                    text-decoration: none;
                }
                .DOR-content-container{
                    width: 90%;
                    margin: auto;
                    border: 1px solid;
                    display: flex;
                    justify-content: space-around;
                    align-items: center;
                    gap: 20px;
                    padding-inline: 15px;
                    margin-bottom: 10px;
                }
                .DOR-body table {
                    width: 90%;
                    margin:auto;
                    border-collapse: collapse; /* Collapse borders */
                    margin-top: 20px;
                    margin-bottom: 30px;
                }
        
                .DOR-body th {
                    background-color: #b93a3a;
                    color: white;
                    padding: 10px;
                    border: 1px solid #cccccc;
                }
        
                .DOR-body td {
                    border: 2px solid #cccccc;
                    padding: 10px;
                    text-align: center;
                }
        
                .DOR-body th:nth-child(1), td:nth-child(1) {
                    width: 20%;
                }
        
                .DOR-body th:nth-child(2), td:nth-child(2) {
                    width: 65%;
                }
        
                .DOR-body th:nth-child(3), td:nth-child(3) {
                    width: 15%;
                }
                .DOR-footer{
                    text-align: center;
                }
                /* @media print {
                } */
            </style>
        </head>
        <body class="DOR-body">
            <div class="DOR-header-code"></div>
            <div class="DOR-header-container">
                <h1 class="DOR-header">Air Delivery</h1>
                <h1 class="DOR-header">اذن تسليم جوي</h1>
            </div>
            <p class="DOR-code">${pOperationHeader.DeliveryOrderSerial}</p>
            <div class="DOR-report-head">
                <div class="DOR-report-head-side">
                    <p>Cust Hours Stock Keeper :  <span></span>  </p>
                    <p>Please deliver To messrs :  <span></span>  </p>
                    <p class="underline-p">Shipment details as below : </p>
                </div>
                <div class="DOR-report-head-side" dir="rtl">
                    <p>السيد مخزنجي مصلحة الجمارك :  <span> <span> </p>
                    <p>برجاء تسليم السادة :  <span>${pOperationHeader.Consignee2Name == 0 ? (pOperationHeader.ConsigneeName == 0 ? "" : pOperationHeader.ConsigneeName) : pOperationHeader.Consignee2Name} </span>  </p>
                    <p class="underline-p">بيانات الشحنة كالتالى</p>
                </div>
            </div>
            <div class="DOR-content-container">
                <div class="DOR-content-section">
                    <p class="underline-p">Air Line : </p><span> ${pOperationHeader.AirlineName} - ${pOperationHeader.AirlinePrefix}</span>
                    <p style="text-decoration: underline;">الخط الجوي</p>
                </div>
                <div class="DOR-content-section">
                    <p class="underline-p">Sailing Date : </p><span> ${(pOperationHeader.ActualDeparture == 0 ? "" : new Date(parseFloat((pOperationHeader.ActualDeparture).slice(6, 19))).toString().slice(0, 15))}</span>
                    <p style="text-decoration: underline;">تاريخ الشحن</p>
                </div>
                <div class="DOR-content-section">
                    <p class="underline-p">A. POL : </p><span> ${pPOLCodeAndName}</span>
                    <p style="text-decoration: underline;">ميناء الشحن</p>
                </div>
            </div>
            <div class="DOR-content-container">
                <div class="DOR-content-section">
                    <p class="underline-p">File NO. : </p><span>${pOperationHeader.Code}</span>
                    <p style="text-decoration: underline;">رقم العملية </p>
                </div>
                <div class="DOR-content-section">
                    <p class="underline-p">Arrival Date : </p><span>  ${(pOperationHeader.ActualArrival == 0 ? "" : new Date(parseFloat((pOperationHeader.ActualArrival).slice(6, 19))).toString().slice(0, 15))}</span>
                    <p style="text-decoration: underline;"> تاريخ الوصول</p>
                </div>
                <div class="DOR-content-section">
                    <p class="underline-p">A. POD : </p><span> ${pPODCodeAndName}</span>
                    <p style="text-decoration: underline;">ميناء الوصول </p>
                </div>
            </div>
            <div class="DOR-content-container">
                <div class="DOR-content-section">
                    <p class="underline-p">Master Bill : </p><span>${(pOperationHeader.MasterBL == 0 ? "" : pOperationHeader.MasterBL)}</span>
                    <p style="text-decoration: underline;">بوليصة كلية رقم </p>
                </div>
                <div class="DOR-content-section">
                    <p class="underline-p">House Bill : </p><span>${(pOperationHeader.HouseBLs == 0 ? (pOperationHeader.HouseNumber == 0 ? "" : pOperationHeader.HouseNumber) : pOperationHeader.HouseBLs)} </span>
                    <p style="text-decoration: underline;"> بوليصة فرعية رقم</p>
                </div>
                <div class="DOR-content-section">
                    <p class="underline-p">Road No : </p><span> ${pٌRoadNumber}</span>
                    <p style="text-decoration: underline;">طريق رقم </p>
                </div>
            </div>
            <table>
                <thead>
                    <tr>
                        <th>Packages</th>
                        <th>Commodity</th>
                        <th>KGS</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>${pOperationHeader.NumberOfPackages}</td>
                        <td>${pOperationHeader.Description}</td>
                        <td>${pOperationHeader.GrossWeightSum} KGM</td>
                    </tr>
                </tbody>
            </table>
            <p class="DOR-footer">مع وافر الشكر على حسن تعاونكم الدائم</p>
            <div><p class="underline-p">Prepared By :</p> <span>${$('#hLoggedUserNameNotLogin').val()}</span></div>
            <div><p class="underline-p">Department :</p> <span>Relan Air FREIGHT</span></div>
            <div><p class="underline-p">Signature :</p> <span></span></div>
        </body>
        </html>
        `;
}
