    var pConsigneeName = data[3];
    var pVesselName = data[4];
    var pLineName = data[5];
    var pMasterBL = data[6];
    var pHouseNumber = data[7];
    var pPOLCodeAndName = data[8];
    var pPODCodeAndName = data[9];
