        ReportHTML += '             <div class="row col-xs-12">';//Serials[0].Serial
        ReportHTML += '             <div class="col-xs-12 text-center" style="font-size: 30px;"><b>اذن شحن <br> SHIPPING ORDER NO: </b>' + Serials[0].Serial + '</div> </div>';
        //ReportHTML += '             <div class=" row col-xs-12 text-right">' + (ConvertDateFormat(GetDateWithFormatMDY(vwRoutings[0].ActualArrival)).toString() == "01/01/1900" ? "" : ConvertDateFormat(GetDateWithFormatMDY(vwRoutings[0].ActualArrival)).toString()) + ' <b>الاسكندرية فى </b> </div>';
        ReportHTML += '       <div class="row col-xs-12" style="font-size: 20px;"><div class="col-xs-3 text-left"> <b>ALEXANDRIA: </b> </div> <div class="col-xs-6 text-center"> ' + (ConvertDateFormat(GetDateWithFormatMDY(vwRoutings[0].ActualArrival)).toString() == "01/01/1900" ? "" : ConvertDateFormat(GetDateWithFormatMDY(vwRoutings[0].ActualArrival)).toString()) + ' </div> <div class="col-xs-3 text-right"> <b>: الاسكندرية فى</b></div></div> ';
        ReportHTML += '       <div class="row col-xs-12" style="font-size: 20px;"><div class="col-xs-3 text-left"> <b>SHIPPER:</b> </div> <div class="col-xs-6 text-center"> ' + (pOperationHeader.ShipperName == 0 ? "" : pOperationHeader.ShipperName) + ' </div> <div class="col-xs-3 text-right"> <b>  : الشاحن  </b></div></div> ';

        ReportHTML += '       <div class="row col-xs-12" style="font-size: 20px;"><div class="col-xs-3 text-left"> <b>VESSEL NAME: </b> </div> <div class="col-xs-6 text-center"> ' + VesselName + ' </div> <div class="col-xs-3 text-right"> <b>: اسم الباخرة </b></div></div> ';
        ReportHTML += '       <div class="row col-xs-12" style="font-size: 20px;"><div class="col-xs-3 text-left"> <b>E.T.A: </b> </div> <div class="col-xs-6 text-center"> ' + (ConvertDateFormat(GetDateWithFormatMDY(vwRoutings[0].ExpectedArrival)).toString() == "01/01/1900" ? "" : ConvertDateFormat(GetDateWithFormatMDY(vwRoutings[0].ExpectedArrival)).toString()) + ' </div> <div class="col-xs-3 text-right"> <b>: تاريخ الوصول</b></div></div> ';

