        //ReportHTML += '             <div class="col-xs-8 m-l m-t-n"><label><input type="checkbox" ' + (pPOrC == 'P' ? ' checked ' : '') + ' disabled="disabled">&nbsp;PrePaid</label>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;';
