function LoadOperationDocPrintLog() {
    if (pDefaults.UnEditableCompanyName != "MES") {
        $('#tblDocsOut th.LastPrint, #tblDocsOut td.LastPrint').addClass('hide');
        return;
    }
    var operationId = Number($('#hOperationID').val());
    if (operationId == 0) {
        return;
    }
    $('#tblDocsOut th.LastPrint, #tblDocsOut td.LastPrint').removeClass('hide');
    $('#tblDocsOut td.LastPrint').text('');
    LoadAll("/api/Operations/LoadOperationDocPrintLog", 'where OperationID=' + operationId + 'or operationid in ( select id from operations where masteroperationid = ' + operationId + ')'
        , function (pData) {
            debugger;
            var data = JSON.parse(pData);
            $.each(data, function (i, item) {
                $('#tblDocsOut tbody tr[id=' + item.DocumentTypeID + '] td.LastPrint').text((item.PrintUserID == 0 ? "" : item.PrintUserName + " " + GetFullDateTime_DD_MM_YY(item.PrintDate)));
            });
        }
        , null);

}
