function getFakeConsignee() {
    debugger;
    let result = "";
    let branchesDetails = JSON.parse(pBranchDefaults);
    let userBranchID = $("#hUserBranchID").val();
    if (branchesDetails.length > 0) {
        let b = branchesDetails.find(item => item.ID == userBranchID);
        result = b.AliasName;
    }
    return result.toUpperCase();
}
