function DocsOut_HBL_TRGL(ReportTypeID){



    var OPHID = $("#slDocsOutOperations").val();
    var OPID = $("#hOperationID").val();
    var arr_Keys = new Array();
    var arr_Values = new Array();
    arr_Keys.push("HID");
    arr_Values.push(OPHID);
    arr_Keys.push("ID");
    arr_Values.push(OPID);
    var ReportName = "";
    var title = "";
    if (($("#cbShowHBLTemplate").prop("checked")) && ReportTypeID == 220 && $("#hTransportType").val() != 2) {
        title = "BL";
        ReportName = "Rep_TRGL_HBL";


    }
    else if ((!$("#cbShowHBLTemplate").prop("checked")) && ReportTypeID == 220 && $("#hTransportType").val() != 2) {
        title = "BL";
        ReportName = "Rep_TRGL_HBLEmpty";

    }
    var pParametersWithValues =
    {
        arr_Keys: arr_Keys
        , arr_Values: arr_Values
        , pTitle: title
        , pReportName: ReportName
    };
    var win = window.open("", "_blank");
    var url = '/ReportMainClass/PrintReport?pTitle="' + pParametersWithValues.pTitle + '"' + '&arr_Keys=' + pParametersWithValues.arr_Keys + '' + '&arr_Values=' + pParametersWithValues.arr_Values + '&pReportName=' + pParametersWithValues.pReportName + '';

    win.location = url;



}